class ConfigRegistroSalarioTiempoServicio extends BaseConfigRegistroSalarioTiempoServicio {

    public static function obtenerObjConfigRegistroSalarioTiempoServicio($idconfig) {
        return Doctrine::getTable('ConfigRegistroSalarioTiempoServicio')->find($idconfig);
    }

    public static function TodoConfigRegistroSalarioTiempoServicio(){
        return Doctrine_Query::create()
            ->select('cts.denominacion,tn.denominacion as denom, tn.idtiponomina as idtiponomina, cva.anotaciones , cvrc.denominacion, cvrc.idconfreportescertificaciones')
            ->from('ConfigRegistroSalarioTiempoServicio cts')
            ->innerJoin('cts.NomTipoNomina tn')
            ->leftJoin('cts.ConfVarAuxSNC225 cva')
            ->leftJoin('cva.ConfVariablesReportesCertificaciones cvrc')
            ->fetchArray();
    }

    public static function obtenerListadoCamposRegistroSalario($idtiponomina){
        return Doctrine_Query::create()
               ->from('ConfigRegistroSalarioTiempoServicio')
               ->where('idtiponomina = ?', array($idtiponomina))
               ->fetchArray();
    }

    public static function obtenerDenominacioDadoIdConf($idconfregistrosalario){
        return Doctrine_Query::create()
            ->select('denominacion')
            ->from('ConfigRegistroSalarioTiempoServicio')
            ->where('idregistsalartiempservc = ?', array($idconfregistrosalario))
            ->fetchOne()
            ->denominacion;
    }
    

}
